B.biR=s(["\u041f\u043e\u0435\u0437\u0434 \u0443\u0435\u0445\u0430\u043b.","\u0413\u0440\u044f\u043d\u0443\u043b \u0433\u0440\u043e\u043c.","\u0421\u043e\u043b\u043d\u0446\u0435 \u0432\u0437\u043e\u0448\u043b\u043e.","\u0427\u0430\u0441\u044b \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0438\u0441\u044c."],t.s)
B.bQL=new A.dp("\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u2014 \u044d\u0442\u043e \u0433\u0440\u0443\u043f\u043f\u0430 \u0441\u043b\u043e\u0432, \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0445 \u043f\u043e \u0441\u043c\u044b\u0441\u043b\u0443 \u0438 \u0432\u044b\u0440\u0430\u0436\u0430\u044e\u0449\u0438\u0445 \u0437\u0430\u043a\u043e\u043d\u0447\u0435\u043d\u043d\u0443\u044e \u043c\u044b\u0441\u043b\u044c. \u041f\u0435\u0440\u0432\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0432 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0441 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0431\u0443\u043a\u0432\u044b, \u0430 \u0432 \u043a\u043e\u043d\u0446\u0435 \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044f \u0442\u043e\u0447\u043a\u0430, \u0432\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0438\u043b\u0438 \u0432\u043e\u0441\u043a\u043b\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0437\u043d\u0430\u043a. \u0413\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043e\u0441\u043d\u043e\u0432\u0430 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u2014 \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0435 (\u043e \u043a\u043e\u043c \u0438\u043b\u0438 \u043e \u0447\u0435\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f, \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u043a\u0442\u043e? \u0447\u0442\u043e?) \u0438 \u0441\u043a\u0430\u0437\u0443\u0435\u043c\u043e\u0435 (\u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u043f\u0440\u0435\u0434\u043c\u0435\u0442, \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442? \u0447\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u043b?). \u0422\u0435\u043a\u0441\u0442 \u0441\u043e\u0441\u0442\u043e\u0438\u0442 \u0438\u0437 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0439, \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u044b\u0445 \u043e\u0431\u0449\u0435\u0439 \u0442\u0435\u043c\u043e\u0439 \u0438 \u043c\u044b\u0441\u043b\u044c\u044e.",B.bes,'\u0414\u0435\u0442\u0438 \u0447\u0430\u0441\u0442\u043e \u0437\u0430\u0431\u044b\u0432\u0430\u044e\u0442 \u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0442\u043e\u0447\u043a\u0443 \u0432 \u043a\u043e\u043d\u0446\u0435 \u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u044e\u0442 \u043d\u043e\u0432\u043e\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u043e\u0439 \u0431\u0443\u043a\u0432\u044b, \u043b\u0438\u0431\u043e \u043f\u0443\u0442\u0430\u044e\u0442 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0441\u043b\u043e\u0432 ("\u0434\u043e\u043c \u043b\u0435\u0442\u0438\u0442 \u0441\u0438\u043d\u0438\u0439 \u0447\u0430\u0448\u043a\u0430") \u0441 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u043c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u043c.',"\u041f\u0435\u0440\u0432\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u043f\u0438\u0448\u0438 \u0441 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0431\u0443\u043a\u0432\u044b! \u0412 \u043a\u043e\u043d\u0446\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0432\u044c \u0442\u043e\u0447\u043a\u0443, \u0432\u043e\u043f\u0440\u043e\u0441 \u0438\u043b\u0438 \u0432\u043e\u0441\u043a\u043b\u0438\u0446\u0430\u043d\u0438\u0435! \u0421\u043b\u043e\u0432\u0430 \u0432 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0434\u0440\u0443\u0436\u0430\u0442 \u043f\u043e \u0441\u043c\u044b\u0441\u043b\u0443!",'\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u041f\u043e\u0441\u043b\u0443\u0448\u0430\u0439\u0442\u0435: \u041a\u043e\u0442 \u0441\u0438\u0434\u0438\u0442 \u043d\u0430 \u0437\u0430\u0431\u043e\u0440\u0435. \u042d\u0442\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435?"\n\u0414\u0435\u0442\u0438: "\u0414\u0430, \u0437\u0434\u0435\u0441\u044c \u043f\u043e\u043d\u044f\u0442\u043d\u0430 \u043c\u044b\u0441\u043b\u044c!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0410 \u0435\u0441\u043b\u0438 \u044f \u0441\u043a\u0430\u0436\u0443: \u0417\u0430\u0431\u043e\u0440\u0435 \u043a\u043e\u0442 \u043d\u0430 \u0441\u0438\u0434\u0438\u0442 \u0437\u0435\u043b\u0435\u043d\u044b\u0439 \u043b\u043e\u0436\u043a\u0430?"\n\u0414\u0435\u0442\u0438: "\u041d\u0435\u0442! \u0421\u043b\u043e\u0432\u0430 \u043f\u043e\u0441\u0441\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u0438 \u043c\u044b\u0441\u043b\u044c \u043f\u0440\u043e\u043f\u0430\u043b\u0430!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u041a\u0442\u043e \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0433\u0435\u0440\u043e\u0439 \u0432 \u043f\u0435\u0440\u0432\u043e\u043c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0438? \u041e \u043a\u043e\u043c \u0440\u0435\u0447\u044c?"\n\u0414\u0435\u0442\u0438: "\u041e \u043a\u043e\u0442\u0435! \u042d\u0442\u043e \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0435!"\n\u0423\u0447\u0438\u0442\u0435\u043b\u044c: "\u0410 \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u043a\u043e\u0442?"\n\u0414\u0435\u0442\u0438: "\u0421\u0438\u0434\u0438\u0442! \u042d\u0442\u043e \u0441\u043a\u0430\u0437\u0443\u0435\u043c\u043e\u0435!"',B.bcd,B.bgp,'\u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043b: "\u043c\u044b \u043f\u043e\u0448\u043b\u0438 \u0432 \u043a\u0438\u043d\u043e \u0442\u0430\u043c \u0431\u044b\u043b\u043e \u0432\u0435\u0441\u0435\u043b\u043e \u0448\u0435\u043b \u0434\u043e\u0436\u0434\u044c". \u041e\u043d \u0433\u043e\u0432\u043e\u0440\u0438\u0442: "\u0417\u0430\u0447\u0435\u043c \u0442\u043e\u0447\u043a\u0438, \u0438 \u0442\u0430\u043a \u0432\u0441\u0451 \u043f\u043e\u043d\u044f\u0442\u043d\u043e!"',B.bLT,"1 - 2 - 3 - 4 - 1","\u0422\u0415\u041a\u0421\u0422","\u0421\u043e\u0441\u0442\u0430\u0432\u044c \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0432\u0441\u0435\u0433\u043e \u0438\u0437 \u0434\u0432\u0443\u0445 \u0441\u043b\u043e\u0432, \u043d\u043e \u0442\u0430\u043a\u043e\u0435, \u0447\u0442\u043e\u0431\u044b \u0432 \u043d\u0435\u043c \u0431\u044b\u043b\u0430 \u044f\u0441\u043d\u0430 \u0446\u0435\u043b\u0430\u044f \u0438\u0441\u0442\u043e\u0440\u0438\u044f.",B.biR,"\u0413\u0440\u044f\u043d\u0443\u043b \u0433\u0440\u043e\u043c. (\u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0435 \u0438 \u0441\u043a\u0430\u0437\u0443\u0435\u043c\u043e\u0435, \u043f\u0435\u0440\u0435\u0434\u0430\u0435\u0442 \u0440\u0435\u0437\u043a\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0433\u043e\u0434\u044b)","\u041d\u0430\u0447\u0430\u043b\u043e \u0441\u0442\u0440\u043e\u043a\u0438 \u0441 \u0437\u0430\u0433\u043b\u0430\u0432\u043d\u043e\u0439 \u0431\u0443\u043a\u0432\u044b, \u0440\u043e\u0432\u043d\u044b\u0435 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u044b \u043c\u0435\u0436\u0434\u0443 \u0441\u043b\u043e\u0432\u0430\u043c\u0438 \u0432 \u0448\u0438\u0440\u0438\u043d\u0443 \u0431\u0443\u043a\u0432\u044b \u041e, \u0447\u0435\u0442\u043a\u0430\u044f \u0442\u043e\u0447\u043a\u0430 \u043d\u0430 \u043b\u0438\u043d\u0438\u0438 \u0441\u0442\u0440\u043e\u043a\u0438.","1. \u041e\u0431\u0440\u0430\u0437\u0435\u0446: \u041f\u0442\u0438\u0446\u044b \u043f\u043e\u044e\u0442 \u2014 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435. 2. \u0422\u0430\u0431\u043b\u0438\u0446\u0430: \u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f: \u041f\u0442\u0438\u0446\u044b \u043f\u043e\u044e\u0442 \u0432 \u0441\u0430\u0434\u0443; \u041b\u0435\u0441 \u0448\u0443\u043c\u0438\u0442 \u0442\u0438\u0445\u043e; \u041a\u043d\u0438\u0433\u0430 \u043b\u0435\u0436\u0438\u0442 \u043d\u0430 \u0441\u0442\u043e\u043b\u0435; \u0421\u043e\u0431\u0430\u043a\u0430 \u0433\u0440\u043e\u043c\u043a\u043e \u043b\u0430\u0435\u0442. \u041d\u0430\u0431\u043e\u0440 \u0441\u043b\u043e\u0432: \u0422\u0440\u0430\u0432\u0430 \u0437\u0435\u043b\u0435\u043d\u0430\u044f \u0431\u0435\u0436\u0438\u0442 \u0447\u0430\u0448\u043a\u0430; \u0421\u0442\u043e\u043b \u043b\u0435\u0442\u0438\u0442 \u0432\u044b\u0441\u043e\u043a\u043e \u043e\u043a\u043d\u043e. 3. \u041e\u0448\u0438\u0431\u043a\u0430 \u041d\u0435\u0437\u043d\u0430\u0439\u043a\u0438: \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u044c \u043d\u0430 \u0442\u0440\u0438 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0441 \u0442\u043e\u0447\u043a\u0430\u043c\u0438. 7. \u0428\u0438\u0444\u0440: \u0422\u0415\u041a\u0421\u0422. 8. \u0422\u0420\u0418\u0417: \u0413\u0440\u044f\u043d\u0443\u043b \u0433\u0440\u043e\u043c.")
B.bGV=s(["\u0417\u043d\u0430\u043a\u0438 \u043f\u0440\u0435\u043f\u0438\u043d\u0430\u043d\u0438\u044f \u2014 \u0434\u043e\u0440\u043e\u0436\u043d\u044b\u0435 \u0437\u043d\u0430\u043a\u0438 \u0434\u043b\u044f \u0433\u043e\u043b\u043e\u0441\u0430: \u0442\u043e\u0447\u043a\u0430 \u2014 \u043a\u0440\u0430\u0441\u043d\u044b\u0439 \u0441\u0432\u0435\u0442 (\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0441\u044c \u0438 \u0432\u0434\u043e\u0445\u043d\u0438), \u0437\u0430\u043f\u044f\u0442\u0430\u044f \u2014 \u0436\u0435\u043b\u0442\u044b\u0439 (\u043f\u0440\u0438\u0442\u043e\u0440\u043c\u043e\u0437\u0438).","\u0412\u044b\u0440\u0430\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0447\u0442\u0435\u043d\u0438\u0435 \u2014 \u043a\u0430\u043a \u043e\u0436\u0438\u0432\u0448\u0438\u0439 \u043c\u0443\u043b\u044c\u0442\u0444\u0438\u043b\u044c\u043c \u0432 \u0432\u043e\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u0441\u043b\u0443\u0448\u0430\u0442\u0435\u043b\u0435\u0439."],t.s)
B.bgi=s(["\u041f\u043e\u0432\u0435\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0447\u0442\u0435\u043d\u0438\u0435 (\u0442\u043e\u0447\u043a\u0430 .)","\u0412\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0447\u0442\u0435\u043d\u0438\u0435 (\u0432\u043e\u043f\u0440\u043e\u0441 ?)","\u0412\u043e\u0441\u043a\u043b\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0447\u0442\u0435\u043d\u0438\u0435 (\u0437\u043d\u0430\u043a !)"],t.s)
